@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@300;500;600;700&display=swap');
body,.fl-page{background-color:#121011!important;}
.fl-page-header{background:transparent!important;-webkit-backdrop-filter:none;backdrop-filter:none;border-bottom:0!important;box-shadow:none!important;}
.fl-page-header-fixed{background:rgba(18,16,17,.72)!important;-webkit-backdrop-filter:blur(16px) saturate(1.3);backdrop-filter:blur(16px) saturate(1.3);border-bottom:1px solid rgba(255,255,255,.09)!important;}
.fl-page-header-wrap,.fl-page-nav-wrap,.fl-page-header .fl-page-nav,.fl-page-header .navbar,.fl-page-header-container,.fl-page-nav-collapse{background:transparent!important;border:0!important;box-shadow:none!important;}
.fl-page-header .fl-page-header-container{max-width:1280px!important;width:calc(100% - 2 * clamp(20px,5vw,64px))!important;margin:0 auto!important;padding-left:0!important;padding-right:0!important;}
@media(min-width:993px){
.fl-page-header .fl-page-header-row{display:flex!important;align-items:center;flex-wrap:nowrap!important;margin:0!important;}
.fl-page-header .fl-page-header-row>*{max-width:none!important;padding-left:0!important;padding-right:0!important;}
.fl-page-header .fl-page-header-row>*:first-child{flex:0 0 auto!important;width:auto!important;}
.fl-page-header .fl-page-header-row>*:last-child{flex:1 1 auto!important;width:auto!important;min-width:0!important;}
.fl-page-header .fl-page-nav,.fl-page-header .fl-page-nav-collapse,.fl-page-header .navbar{width:100%!important;flex-wrap:nowrap!important;}
.fl-page-header .fl-theme-menu{display:flex!important;align-items:center;gap:30px;width:100%;flex-wrap:nowrap!important;float:none!important;margin:0!important;}
.fl-page-header .fl-theme-menu>li{white-space:nowrap;}
.fl-page-header .fl-theme-menu>li:first-child{margin-left:auto;}
.fl-page-header .fl-theme-menu>li.rl-cta{margin-left:auto;}
}
.fl-page-header-logo a{display:inline-flex;align-items:center;gap:10px;text-decoration:none;}
.fl-page-header-logo a::before{content:'';width:18px;height:18px;background:#990000;transform:skewX(-12deg);display:inline-block;flex:0 0 auto;}
.fl-logo-text{color:#FBFAF7!important;font-family:'Oswald',sans-serif!important;font-weight:700!important;text-transform:uppercase;letter-spacing:.03em;font-size:22px!important;line-height:1!important;}
.fl-page-header .fl-theme-menu li a,.fl-page-header .navbar-nav li a{color:#D6D1C8!important;font-family:'Oswald',sans-serif!important;font-weight:500!important;text-transform:uppercase!important;letter-spacing:.06em;font-size:15px!important;background:transparent!important;border:0!important;border-bottom:2px solid transparent!important;transition:color .15s,border-color .15s;}
.fl-page-header .fl-theme-menu li a:hover{color:#FBFAF7!important;text-decoration:none!important;}
.fl-page-header .fl-theme-menu li.current-menu-item>a{color:#FBFAF7!important;border-bottom:2px solid #990000!important;}
.fl-page-header .fl-theme-menu li.rl-cta a{background:#990000!important;color:#FBFAF7!important;padding:10px 18px!important;border:0!important;border-bottom:0!important;}
.fl-page-header .fl-theme-menu li.rl-cta a:hover{box-shadow:0 0 0 1px #990000,0 8px 24px -8px rgba(153,0,0,.7);color:#FBFAF7!important;}
.fl-page-nav .navbar-toggler,.fl-page-nav .navbar-toggle,.fl-page-nav .navbar-toggle span{color:#FBFAF7!important;border-color:rgba(255,255,255,.25)!important;}
.fl-page-header .fl-page-nav-search,.fl-page-header-search,.fl-page-header .fl-search-form{display:none!important;}
